local mainMod = "SUPER"

hl.bind("SUPER + R", hl.dsp.submap("resize"))

hl.define_submap("resize", function()
    hl.bind("h", hl.dsp.window.resize({ x = -10, y = 0, relative = true }), { repeating = true })
    hl.bind("j", hl.dsp.window.resize({ x = 0, y = 10, relative = true }), { repeating = true })
    hl.bind("k", hl.dsp.window.resize({ x = 0, y = -10, relative = true }), { repeating = true })
    hl.bind("l", hl.dsp.window.resize({ x = 10, y = 0, relative = true }), { repeating = true })

    hl.bind("escape", hl.dsp.submap("reset"))
end)


hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd("kitty"))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exit())
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(
    mainMod .. " + SUPER_L",
    hl.dsp.exec_cmd("pkill wofi || wofi --show drun --gtk-dark"),
    { release = true }
)
hl.bind(mainMod .. " + P", hl.dsp.window.pin())
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind(
    mainMod .. " + SHIFT + F",
    hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" })
)
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("hyprlock"))

local fade_in = "hyprctl keyword animation \"fadeOut,0,0,default\""
local fade_out = "hyprctl keyword animation \"fadeOut,1,4,default\""
local screenshotarea = fade_in .. " ; grimblast --notify copy area; " .. fade_out 
hl.bind("Print", hl.dsp.exec_cmd(screenshotarea))
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd("grimblast --notify --cursor copy screen"))
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("grimblast --notify --cursor copy output"))
hl.bind("ALT + Print", hl.dsp.exec_cmd("grimblast --notify --cursor copy active"))
hl.bind("ALT + SHIFT + F23", hl.dsp.exec_cmd(screenshotarea))

