hl.on("hyprland.start", function()
    -- color temperature depending on time of day
    hl.exec_cmd("wlsunset -l 38.9 -L -9")
    hl.exec_cmd("waybar")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("warp-taskbar")
    hl.exec_cmd("dunst")
    hl.exec_cmd("hypridle")
    hl.exec_cmd("brightnessctl set 30%")
    hl.exec_cmd("warp-cli tunnel host add mail.tecnico.ulisboa.pt")
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("kitty", { workspace = "1 silent" })
    hl.exec_cmd("kitty", { workspace = "10 silent" })
    hl.exec_cmd(
        "brave --enable-features=TouchpadOverscrollHistoryNavigation,UseOzonePlatform",
        { workspace = "3 silent" }
    )
    hl.exec_cmd("slack", { workspace = "4 silent" })
    hl.exec_cmd("thunderbird", { workspace = "5 silent" })
    hl.exec_cmd("tidal-hifi", { workspace = "9 silent" })
end)

hl.on("config.reloaded", function()
    hl.exec_cmd("hyprpaper")
end)

